<div id="stepTitle" style="font-weight:bold;font-size:12px;margin-top:2px;"></div>
<div id="stepText" style="font-size:11px;line-height:1.4;color:#333;"></div>

<div style="font-size:10px;color:#777;line-height:1.35;margin-top:4px;">
  Drag in the figure to orbit: the dashed <span style="color:#E8622A">r</span> really lies flat in the xy-plane
  and the drop to it is truly vertical.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   z-axis (world +Y)      → Line black, -0.4…6   + ConeGeometry(0.12,0.35) black
   y-axis (world +X)      → Line black, -0.4…6   + ConeGeometry(0.12,0.35) black
   x-axis (world +Z)      → Line black, -0.4…5   + ConeGeometry(0.12,0.35) black
   point P                → SphereGeometry(0.09) black
   rho segment            → CylinderGeometry(0.035,0.035,1,12) blue #1F5C8B
   r segment (ground)     → Line dashed orange #E8622A (0.18/0.12)
   z drop (vertical)      → Line dashed orange #E8622A
   right-angle square @Q  → Line orange, 3 pts, side 0.3, in vertical plane of r
   phi arc                → Line black, R 0.9, z-axis → rho + cone arrowhead
   theta arc              → Line black, R 0.8, +x-axis → r (ground) + cone arrowhead
   rectangular projections→ 4 dashed Lines gray-green #6B8E7B (O–A–Q, O–B–Q)
   labels                 → addLabel (z, y, x, P(...), rho, phi, theta, r, z, x, y)
   World mapping: math x → world Z (toward viewer), math y → world X (right),
                  math z → world Y (up)
─────────────────────────────────────────────────────────────────────────── */

const C_AX = 0x000000, C_RHO = 0x1F5C8B, C_OR = 0xE8622A, C_PR = 0x5F8A76;
const UPV = new THREE.Vector3(0, 1, 0);
const ORG = new THREE.Vector3(0, 0, 0);
const DEG = THREE.MathUtils.degToRad;

const S = { rho: 5, theta: 65, phi: 60, mode: 'sph' };

/* ── helpers ─────────────────────────────────────────────────────────────── */
function mkLine(n, mat) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 3), 3));
  const l = new THREE.Line(g, mat);
  l.frustumCulled = false;
  scene.add(l);
  return l;
}
function setPts(line, pts) {
  const a = line.geometry.attributes.position;
  const n = a.count;
  for (let i = 0; i < n; i++) {
    const p = pts[Math.min(i, pts.length - 1)];
    a.setXYZ(i, p.x, p.y, p.z);
  }
  a.needsUpdate = true;
  line.geometry.computeBoundingSphere();
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}
function solidMat(c) { return new THREE.LineBasicMaterial({ color: c, transparent: true, opacity: 1 }); }
function dashMat(c) {
  return new THREE.LineDashedMaterial({ color: c, dashSize: 0.18, gapSize: 0.12, transparent: true, opacity: 1 });
}
function cone(c, rad, h) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, h, 16),
    new THREE.MeshBasicMaterial({ color: c, transparent: true, opacity: 1 }));
  scene.add(m);
  return m;
}
function orient(mesh, dir) {
  const d2 = dir.clone();
  if (d2.lengthSq() < 1e-12) return;
  mesh.quaternion.setFromUnitVectors(UPV, d2.normalize());
}

/* ── axes ────────────────────────────────────────────────────────────────── */
const axMat = solidMat(C_AX);
const STUB = 0.4, LZ = 6.0, LY = 6.0, LX = 5.0;

const axZ = mkLine(2, axMat); setPts(axZ, [new THREE.Vector3(0, -STUB, 0), new THREE.Vector3(0, LZ, 0)]);
const axY = mkLine(2, axMat); setPts(axY, [new THREE.Vector3(-STUB, 0, 0), new THREE.Vector3(LY, 0, 0)]);
const axX = mkLine(2, axMat); setPts(axX, [new THREE.Vector3(0, 0, -STUB), new THREE.Vector3(0, 0, LX)]);

const tipZ = cone(C_AX, 0.13, 0.38); tipZ.position.set(0, LZ + 0.19, 0); orient(tipZ, new THREE.Vector3(0, 1, 0));
const tipY = cone(C_AX, 0.13, 0.38); tipY.position.set(LY + 0.19, 0, 0); orient(tipY, new THREE.Vector3(1, 0, 0));
const tipX = cone(C_AX, 0.13, 0.38); tipX.position.set(0, 0, LX + 0.19); orient(tipX, new THREE.Vector3(0, 0, 1));

/* ── point P ─────────────────────────────────────────────────────────────── */
const ptP = new THREE.Mesh(new THREE.SphereGeometry(0.09, 20, 14),
  new THREE.MeshBasicMaterial({ color: 0x000000 }));
scene.add(ptP);

/* ── rho segment ─────────────────────────────────────────────────────────── */
const rhoMat = new THREE.MeshBasicMaterial({ color: C_RHO, transparent: true, opacity: 1 });
const rhoSeg = new THREE.Mesh(new THREE.CylinderGeometry(0.038, 0.038, 1, 14), rhoMat);
scene.add(rhoSeg);

/* ── orange construction ─────────────────────────────────────────────────── */
const rMat = dashMat(C_OR), zMat = dashMat(C_OR), raMat = solidMat(C_OR);
const rLine = mkLine(2, rMat);
const zLine = mkLine(2, zMat);
const raLine = mkLine(3, raMat);

/* ── arcs ────────────────────────────────────────────────────────────────── */
const NA = 60;
const arcPhiMat = solidMat(C_AX), arcThMat = solidMat(C_AX);
const arcPhi = mkLine(NA + 1, arcPhiMat);
const arcTh = mkLine(NA + 1, arcThMat);
const tipPhi = cone(C_AX, 0.075, 0.22);
const tipTh = cone(C_AX, 0.075, 0.22);
const R_PHI = 0.9, R_TH = 0.8;

/* ── rectangular projection rectangle ────────────────────────────────────── */
const prMat = dashMat(C_PR);
const prOA = mkLine(2, prMat);   // origin → A on math-x axis (world Z)
const prAQ = mkLine(2, prMat);
const prOB = mkLine(2, prMat);   // origin → B on math-y axis (world X)
const prBQ = mkLine(2, prMat);

/* ── camera (after geometry) ─────────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.68
});
document.getElementById('btnReset').style.display = '';

/* ── labels ──────────────────────────────────────────────────────────────── */
const AXF = '15px';
const lZ = addLabel('<i>z</i>', new THREE.Vector3(0, LZ + 0.45, 0), { fontSize: AXF, bold: true, offset: [-12, -6] });
const lY = addLabel('<i>y</i>', new THREE.Vector3(LY + 0.45, 0, 0), { fontSize: AXF, bold: true, offset: [6, 16] });
const lX = addLabel('<i>x</i>', new THREE.Vector3(0, 0, LX + 0.45), { fontSize: AXF, bold: true, offset: [-14, 8] });

const lP = addLabel('P(<i>x</i>, <i>y</i>, <i>z</i>)<br>P(<i>&rho;</i>, <i>&theta;</i>, <i>&phi;</i>)',
  new THREE.Vector3(0, 0, 0), { fontSize: '14px', offset: [56, -26] });
lP.div.style.textAlign = 'left';
lP.div.style.lineHeight = '1.35';

const lRho = addLabel('<i>&rho;</i>', new THREE.Vector3(0, 0, 0), { color: '#1F5C8B', fontSize: '17px', offset: [-6, -14] });
const lPhi = addLabel('<i>&phi;</i>', new THREE.Vector3(0, 0, 0), { fontSize: '16px', offset: [-14, -2] });
const lTh = addLabel('<i>&theta;</i>', new THREE.Vector3(0, 0, 0), { fontSize: '16px', offset: [0, 4] });
const lR = addLabel('<i>r</i>', new THREE.Vector3(0, 0, 0), { color: '#E8622A', fontSize: '16px', offset: [0, 18] });
const lZd = addLabel('<i>z</i>', new THREE.Vector3(0, 0, 0), { color: '#E8622A', fontSize: '16px', offset: [16, 0] });
const lPx = addLabel('<i>x</i>', new THREE.Vector3(0, 0, 0), { color: '#5F8A76', fontSize: '14px', offset: [-12, 10] });
const lPy = addLabel('<i>y</i>', new THREE.Vector3(0, 0, 0), { color: '#5F8A76', fontSize: '14px', offset: [4, 16] });

/* ── opacity groups (crossfade between readouts) ─────────────────────────── */
const GROUPS = {
  rho: { mats: [rhoMat], labs: [lRho] },
  phi: { mats: [arcPhiMat, tipPhi.material], labs: [lPhi] },
  theta: { mats: [arcThMat, tipTh.material], labs: [lTh] },
  r: { mats: [rMat, raMat], labs: [lR] },
  zc: { mats: [zMat], labs: [lZd] },
  proj: { mats: [prMat], labs: [lPx, lPy] }
};
const TARGETS = {
  sph: { rho: 1.00, phi: 1.00, theta: 1.00, r: 0.45, zc: 0.45, proj: 0.00 },
  cyl: { rho: 0.18, phi: 0.12, theta: 1.00, r: 1.00, zc: 1.00, proj: 0.00 },
  rect: { rho: 0.18, phi: 0.10, theta: 0.18, r: 0.30, zc: 1.00, proj: 1.00 }
};
const curOp = Object.assign({}, TARGETS.sph);

function applyOpacity() {
  for (const k in GROUPS) {
    const o = curOp[k];
    GROUPS[k].mats.forEach(m => { m.opacity = o; m.visible = o > 0.02; });
    GROUPS[k].labs.forEach(L => { L.div.style.opacity = o < 0.04 ? 0 : o; });
  }
}

/* ── geometry update ─────────────────────────────────────────────────────── */
const _P = new THREE.Vector3(), _Q = new THREE.Vector3(), _vr = new THREE.Vector3();

function update() {
  const rho = S.rho, th = DEG(S.theta), ph = DEG(S.phi);
  const r = rho * Math.sin(ph);
  const mz = rho * Math.cos(ph);
  const mx = r * Math.cos(th), my = r * Math.sin(th);

  _P.set(my, mz, mx);
  _Q.set(my, 0, mx);
  _vr.set(Math.sin(th), 0, Math.cos(th));

  ptP.position.copy(_P);

  // rho cylinder
  const len = _P.length();
  if (len > 0.02) {
    rhoSeg.visible = true;
    rhoSeg.position.copy(_P).multiplyScalar(0.5);
    orient(rhoSeg, _P.clone());
    rhoSeg.scale.set(1, len, 1);
  } else rhoSeg.visible = false;

  // orange construction
  setPts(rLine, [ORG, _Q]); rLine.visible = r > 0.03;
  setPts(zLine, [_Q, _P]); zLine.visible = Math.abs(mz) > 0.03;

  const s = 0.3;
  const u = _vr.clone().multiplyScalar(-s);
  const w = new THREE.Vector3(0, mz >= 0 ? s : -s, 0);
  setPts(raLine, [_Q.clone().add(u), _Q.clone().add(u).add(w), _Q.clone().add(w)]);
  raLine.visible = r > 0.5 && Math.abs(mz) > 0.5;

  // phi arc: from +Y toward vr
  const pPts = [];
  for (let i = 0; i <= NA; i++) {
    const t = ph * i / NA;
    pPts.push(new THREE.Vector3(
      Math.sin(t) * R_PHI * _vr.x,
      Math.cos(t) * R_PHI,
      Math.sin(t) * R_PHI * _vr.z));
  }
  setPts(arcPhi, pPts);
  const showPhi = S.phi > 3 && rho > 0.05;
  arcPhi.visible = showPhi; tipPhi.visible = showPhi;
  if (showPhi) {
    const e = pPts[NA];
    const tg = new THREE.Vector3(Math.cos(ph) * _vr.x, -Math.sin(ph), Math.cos(ph) * _vr.z);
    tipPhi.position.copy(e); orient(tipPhi, tg);
    const mid = pPts[Math.round(NA / 2)].clone().multiplyScalar(1.42);
    lPhi.pos.copy(mid);
  }

  // theta arc in ground plane: +Z (math +x) → vr
  const tPts = [];
  for (let i = 0; i <= NA; i++) {
    const t = th * i / NA;
    tPts.push(new THREE.Vector3(Math.sin(t) * R_TH, 0, Math.cos(t) * R_TH));
  }
  setPts(arcTh, tPts);
  const showTh = S.theta > 3 && r > 0.25;
  arcTh.visible = showTh; tipTh.visible = showTh;
  if (showTh) {
    tipTh.position.copy(tPts[NA]);
    tipTh.quaternion.setFromUnitVectors(UPV,
      new THREE.Vector3(Math.cos(th), 0, -Math.sin(th)).normalize());
    const tm = th / 2;
    lTh.pos.set(Math.sin(tm) * R_TH * 1.45, 0, Math.cos(tm) * R_TH * 1.45);
  }

  // rectangular projections
  const A = new THREE.Vector3(0, 0, mx);   // (x,0,0) in math coords
  const B = new THREE.Vector3(my, 0, 0);   // (0,y,0) in math coords
  setPts(prOA, [ORG, A]); setPts(prAQ, [A, _Q]);
  setPts(prOB, [ORG, B]); setPts(prBQ, [B, _Q]);
  lPx.pos.copy(A).multiplyScalar(0.5);
  lPy.pos.copy(B).multiplyScalar(0.5);

  // dynamic labels
  lP.pos.copy(_P);
  lRho.pos.copy(_P).multiplyScalar(0.5);
  lR.pos.copy(_Q).multiplyScalar(0.5);
  lZd.pos.copy(_Q).lerp(_P, 0.5);

  refreshReadout();
}

/* ── readout ─────────────────────────────────────────────────────────────── */
const elRead = document.getElementById('readout');
function f3(v) { return String(Number(v.toPrecision(3))); }
function refreshReadout() {
  const rho = S.rho, th = DEG(S.theta), ph = DEG(S.phi);
  const r = rho * Math.sin(ph), mz = rho * Math.cos(ph);
  const mx = r * Math.cos(th), my = r * Math.sin(th);
  let h;
  if (S.mode === 'rect') {
    h = '<b>Rectangular</b><br>x = ' + f3(mx) + '<br>y = ' + f3(my) + '<br>z = ' + f3(mz);
  } else if (S.mode === 'cyl') {
    h = '<b>Cylindrical</b><br>r = ' + f3(r) + '<br>&theta; = ' + f3(S.theta) + '&deg;<br>z = ' + f3(mz);
  } else {
    h = '<b>Spherical</b><br>&rho; = ' + f3(rho) + '<br>&theta; = ' + f3(S.theta) + '&deg;<br>&phi; = ' + f3(S.phi) + '&deg;';
  }
  elRead.innerHTML = h;
  document.getElementById('vrho').textContent = f3(S.rho);
  document.getElementById('vth').textContent = f3(S.theta) + '\u00B0';
  document.getElementById('vph').textContent = f3(S.phi) + '\u00B0';
}

/* ── controls ────────────────────────────────────────────────────────────── */
const sRho = document.getElementById('sRho');
const sTheta = document.getElementById('sTheta');
const sPhi = document.getElementById('sPhi');

function syncSliders() {
  sRho.value = S.rho; sTheta.value = S.theta; sPhi.value = S.phi;
}
function onSlide() {
  tween = null; stopPlay();
  S.rho = +sRho.value; S.theta = +sTheta.value; S.phi = +sPhi.value;
  update();
}
sRho.addEventListener('input', onSlide);
sTheta.addEventListener('input', onSlide);
sPhi.addEventListener('input', onSlide);

const btnRect = document.getElementById('mRect');
const btnCyl = document.getElementById('mCyl');
const btnSph = document.getElementById('mSph');
function setMode(m) {
  S.mode = m;
  btnRect.classList.toggle('active', m === 'rect');
  btnCyl.classList.toggle('active', m === 'cyl');
  btnSph.classList.toggle('active', m === 'sph');
  refreshReadout();
}
btnRect.addEventListener('click', () => { stopPlay(); setMode('rect'); });
btnCyl.addEventListener('click', () => { stopPlay(); setMode('cyl'); });
btnSph.addEventListener('click', () => { stopPlay(); setMode('sph'); });

/* ── demo steps ──────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The spherical triple', text: 'One distance \u03C1 and two angles \u03B8 and \u03C6 pin down P. The blue segment is \u03C1, the arc at the z-axis is \u03C6, and the arc in the floor is \u03B8.', st: { rho: 5, theta: 65, phi: 60, mode: 'sph' } },
  { title: 'Stretch \u03C1', text: 'Increasing \u03C1 pushes P straight out along the same ray. Both angles are untouched, so the direction is fixed and only the distance changes.', st: { rho: 6, theta: 65, phi: 60, mode: 'sph' } },
  { title: 'Swing \u03B8', text: '\u03B8 rotates the entire triangle about the z-axis. The height z and the ground distance r stay the same \u2014 P traces a horizontal circle.', st: { rho: 5, theta: 140, phi: 60, mode: 'sph' } },
  { title: 'Tip \u03C6 toward the pole', text: 'Shrinking \u03C6 tilts \u03C1 up toward the z-axis: the dashed r collapses while the dashed z grows, since r = \u03C1 sin \u03C6 and z = \u03C1 cos \u03C6.', st: { rho: 5, theta: 65, phi: 25, mode: 'sph' } },
  { title: 'Same point, cylindrical', text: 'Hold the point still and read it as (r, \u03B8, z). The orange ground segment and orange vertical drop are the featured quantities \u2014 \u03B8 carries over unchanged.', st: { rho: 5, theta: 65, phi: 60, mode: 'cyl' } },
  { title: 'Same point, rectangular', text: 'Finally read it as (x, y, z): r splits into x = r cos \u03B8 and y = r sin \u03B8, while z is the same vertical drop all three systems share.', st: { rho: 5, theta: 65, phi: 60, mode: 'rect' } }
];
let stepIdx = 0, tween = null, playTimer = null;
const elTitle = document.getElementById('stepTitle');
const elText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  elTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + s.title;
  elText.textContent = s.text;
  setMode(s.st.mode);
  tween = {
    from: { rho: S.rho, theta: S.theta, phi: S.phi },
    to: { rho: s.st.rho, theta: s.st.theta, phi: s.st.phi },
    t0: performance.now(), dur: 900
  };
}
document.getElementById('bNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('bPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
const bPlay = document.getElementById('bPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; bPlay.textContent = '\u25B6 Play'; bPlay.classList.remove('active'); }
}
bPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  bPlay.textContent = '\u2016 Pause'; bPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 3600);
});

/* ── interactive explainers ──────────────────────────────────────────────── */
registerInteractive(ptP, {
  title: 'The point P',
  tooltip: 'One point, three names',
  body: 'The same fixed point is written P(x, y, z) in rectangular coordinates, P(r, \u03B8, z) in cylindrical, and P(\u03C1, \u03B8, \u03C6) in spherical. \u03B8 and z are shared between systems.'
});
registerInteractive(rhoSeg, {
  title: '\u03C1 \u2014 distance from the origin',
  tooltip: '\u03C1 = \u221A(x\u00B2+y\u00B2+z\u00B2)',
  body: '\u03C1 is the straight-line distance from the origin to P. Its ground shadow is r = \u03C1 sin \u03C6 and its height is z = \u03C1 cos \u03C6.'
});

/* ── animation: tween state + crossfade opacity ──────────────────────────── */
function figTick() {
  requestAnimationFrame(figTick);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    S.rho = tween.from.rho + (tween.to.rho - tween.from.rho) * e;
    S.theta = tween.from.theta + (tween.to.theta - tween.from.theta) * e;
    S.phi = tween.from.phi + (tween.to.phi - tween.from.phi) * e;
    syncSliders();
    update();
    if (k >= 1) tween = null;
  }
  const tg = TARGETS[S.mode];
  for (const k in tg) curOp[k] += (tg[k] - curOp[k]) * 0.12;
  applyOpacity();
}

/* ── init ────────────────────────────────────────────────────────────────── */
syncSliders();
setMode('sph');
update();
applyOpacity();
elTitle.textContent = '1/' + STEPS.length + '  ' + STEPS[0].title;
elText.textContent = STEPS[0].text;
figTick();
// @FIGURE_CODE_END

