function figTick() {
  requestAnimationFrame(figTick);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    S.rho = tween.from.rho + (tween.to.rho - tween.from.rho) * e;
    S.theta = tween.from.theta + (tween.to.theta - tween.from.theta) * e;
    S.phi = tween.from.phi + (tween.to.phi - tween.from.phi) * e;
    syncSliders();
    update();
    if (k >= 1) tween = null;
  }
