// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   z-axis (world +Y)      → Line black, -0.35…4.3 + ConeGeometry(0.12,0.34) black
   y-axis (world +X)      → Line black, -0.35…4.5 + ConeGeometry(0.12,0.34) black
   x-axis (world +Z)      → Line black, -0.35…3.1 + ConeGeometry(0.12,0.34) black
   point P                → SphereGeometry(0.09) black
   rho segment            → CylinderGeometry(0.040) blue #1F5C8B (solid, full opacity)
   r segment (ground)     → InstancedMesh dash-tubes, orange #E8622A (dash .20/gap .13)
   z drop (vertical)      → InstancedMesh dash-tubes, orange #E8622A
   right-angle square @Q  → 2 × CylinderGeometry(0.022) orange, side 0.3,
                            in the vertical plane containing r and the drop
   phi arc                → Line black, R 0.85, z-axis → rho, + cone arrowhead
   theta arc              → Line black, R 0.75, +x-axis → r (ground), + cone arrow
   rect projections       → 4 dash-tube runs gray-green #5F8A76 (O–A–Q, O–B–Q),
                            fully hidden outside rectangular mode
   hover proxies          → transparent CylinderGeometry along rho / r / z
   labels                 → addLabel, italic serif (z, y, x, P(..), rho, phi,
                            theta, r, z, x, y)
   World mapping: math x → world +Z (recedes to viewer's lower-left),
                  math y → world +X (screen right),
                  math z → world +Y (up)
   Camera: orthographic, axisScreenAngles {x:5.5, z:58} → az ≈ 77°, el ≈ 23°
─────────────────────────────────────────────────────────────────────────── */

const C_AX = 0x000000, C_RHO = 0x1F5C8B, C_OR = 0xE8622A, C_PR = 0x5F8A76;
const UPV = new THREE.Vector3(0, 1, 0);
const ORG = new THREE.Vector3(0, 0, 0);
const DEG = THREE.MathUtils.degToRad;
const SERIF = 'Georgia,"Times New Roman",serif';
const DUMMY = new THREE.Object3D();

const S = { rho: 5, theta: 65, phi: 60, mode: 'sph' };

/* ── helpers ─────────────────────────────────────────────────────────────── */
function mkLine(n, mat) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 3), 3));
  const l = new THREE.Line(g, mat);
  l.frustumCulled = false;
  scene.add(l);
  return l;
}
function setPts(line, pts) {
  const a = line.geometry.attributes.position;
  for (let i = 0; i < a.count; i++) {
    const p = pts[Math.min(i, pts.length - 1)];
    a.setXYZ(i, p.x, p.y, p.z);
  }
  a.needsUpdate = true;
  line.geometry.computeBoundingSphere();
}
function solidMat(c) { return new THREE.LineBasicMaterial({ color: c, transparent: true, opacity: 1 }); }
function cone(c, rad, h) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, h, 18),
    new THREE.MeshBasicMaterial({ color: c, transparent: true, opacity: 1 }));
  scene.add(m);
  return m;
}
function orient(mesh, dir) {
  const d2 = dir.clone();
  if (d2.lengthSq() < 1e-12) return;
  mesh.quaternion.setFromUnitVectors(UPV, d2.normalize());
}
function makeTube(color, radius) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, 1, 10),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 }));
  m.frustumCulled = false;
  scene.add(m);
  return m;
}
function spanTube(mesh, a, b) {
  const v = b.clone().sub(a);
  const len = v.length();
  if (len < 1e-4) { mesh.visible = false; return; }
  mesh.visible = true;
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  orient(mesh, v);
  mesh.scale.set(1, len, 1);
}
// real-thickness dashed segment: a run of short instanced cylinders
function makeDashTube(color, radius, maxN) {
  const geo = new THREE.CylinderGeometry(radius, radius, 1, 8);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const inst = new THREE.InstancedMesh(geo, mat, maxN);
  inst.frustumCulled = false;
  inst.count = 0;
  scene.add(inst);
  const q = new THREE.Quaternion();
  return {
    object: inst, material: mat,
    clear() { inst.count = 0; },
    set(a, b, dash, gap) {
      dash = dash || 0.20; gap = gap || 0.13;
      const dir = b.clone().sub(a);
      const L = dir.length();
      if (L < 0.04) { inst.count = 0; return; }
      dir.divideScalar(L);
      q.setFromUnitVectors(UPV, dir);
      let n = Math.max(1, Math.round((L + gap) / (dash + gap)));
      n = Math.min(n, maxN);
      let dl = (L - (n - 1) * gap) / n;
      if (dl <= 0.02) { n = 1; dl = L; }
      for (let i = 0; i < n; i++) {
        const c = i * (dl + gap) + dl / 2;
        DUMMY.position.copy(a).addScaledVector(dir, c);
        DUMMY.quaternion.copy(q);
        DUMMY.scale.set(1, dl, 1);
        DUMMY.updateMatrix();
        inst.setMatrixAt(i, DUMMY.matrix);
      }
      inst.count = n;
      inst.instanceMatrix.needsUpdate = true;
    }
  };
}
// italic-serif label wrapper (keeps the textbook's math typography)
function mathLabel(html, pos, o) {
  const e = addLabel(html, pos, o);
  e.div.style.fontFamily = SERIF;
  return e;
}
// invisible but ray-castable proxy tube used for hover explanations
function proxyTube(r) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 1, 8),
    new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
  scene.add(m);
  return m;
}

/* ── axes ────────────────────────────────────────────────────────────────── */
const axMat = solidMat(C_AX);
const STUB = 0.35, LZ = 4.3, LY = 4.5, LX = 3.1;

const axZ = mkLine(2, axMat); setPts(axZ, [new THREE.Vector3(0, -STUB, 0), new THREE.Vector3(0, LZ, 0)]);
const axY = mkLine(2, axMat); setPts(axY, [new THREE.Vector3(-STUB, 0, 0), new THREE.Vector3(LY, 0, 0)]);
const axX = mkLine(2, axMat); setPts(axX, [new THREE.Vector3(0, 0, -STUB), new THREE.Vector3(0, 0, LX)]);

const tipZ = cone(C_AX, 0.12, 0.34); tipZ.position.set(0, LZ + 0.17, 0); orient(tipZ, new THREE.Vector3(0, 1, 0));
const tipY = cone(C_AX, 0.12, 0.34); tipY.position.set(LY + 0.17, 0, 0); orient(tipY, new THREE.Vector3(1, 0, 0));
const tipX = cone(C_AX, 0.12, 0.34); tipX.position.set(0, 0, LX + 0.17); orient(tipX, new THREE.Vector3(0, 0, 1));

/* ── point P ─────────────────────────────────────────────────────────────── */
const ptP = new THREE.Mesh(new THREE.SphereGeometry(0.095, 20, 14),
  new THREE.MeshBasicMaterial({ color: 0x000000 }));
scene.add(ptP);

/* ── rho segment ─────────────────────────────────────────────────────────── */
const rhoMat = new THREE.MeshBasicMaterial({ color: C_RHO, transparent: true, opacity: 1 });
const rhoSeg = new THREE.Mesh(new THREE.CylinderGeometry(0.040, 0.040, 1, 14), rhoMat);
scene.add(rhoSeg);

/* ── orange construction ─────────────────────────────────────────────────── */
const rDash = makeDashTube(C_OR, 0.030, 48);
const zDash = makeDashTube(C_OR, 0.030, 48);
const raMat = new THREE.MeshBasicMaterial({ color: C_OR, transparent: true, opacity: 1 });
const raA = new THREE.Mesh(new THREE.CylinderGeometry(0.023, 0.023, 1, 8), raMat);
const raB = new THREE.Mesh(new THREE.CylinderGeometry(0.023, 0.023, 1, 8), raMat);
raA.frustumCulled = false; raB.frustumCulled = false;
scene.add(raA); scene.add(raB);
const proxyR = proxyTube(0.14);
const proxyZ = proxyTube(0.14);

/* ── arcs ────────────────────────────────────────────────────────────────── */
const NA = 60;
const arcPhiMat = solidMat(C_AX), arcThMat = solidMat(C_AX);
const arcPhi = mkLine(NA + 1, arcPhiMat);
const arcTh = mkLine(NA + 1, arcThMat);
const tipPhi = cone(C_AX, 0.07, 0.20);
const tipTh = cone(C_AX, 0.07, 0.20);
const R_PHI = 0.85, R_TH = 0.75;

/* ── rectangular projection rectangle (hidden unless rectangular mode) ───── */
const prOA = makeDashTube(C_PR, 0.024, 40);   // origin → A on math-x axis (world Z)
const prAQ = makeDashTube(C_PR, 0.024, 40);
const prOB = makeDashTube(C_PR, 0.024, 40);   // origin → B on math-y axis (world X)
const prBQ = makeDashTube(C_PR, 0.024, 40);
const PROJ = [prOA, prAQ, prOB, prBQ];

/* ── camera (after geometry) ─────────────────────────────────────────────── */
// Measured off the source: the y-axis leaves the origin nearly horizontally
// (~5.5° below screen horizontal) while the x-axis plunges toward the viewer's
// lower-left (~58°). Axes are kept short relative to ρ so P lands high and far
// to the upper right, as in the printed figure.
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 5.5, z: 58 },
  heightFraction: 0.66
});
document.getElementById('btnReset').style.display = '';

/* ── labels ──────────────────────────────────────────────────────────────── */
const AXF = '16px';
const lZ = mathLabel('<i>z</i>', new THREE.Vector3(0, LZ + 0.34, 0), { fontSize: AXF, bold: true, offset: [-14, -8] });
const lY = mathLabel('<i>y</i>', new THREE.Vector3(LY + 0.34, 0, 0), { fontSize: AXF, bold: true, offset: [10, 16] });
const lX = mathLabel('<i>x</i>', new THREE.Vector3(0, 0, LX + 0.34), { fontSize: AXF, bold: true, offset: [-18, 8] });

const lP = mathLabel('', new THREE.Vector3(0, 0, 0), { fontSize: '15px', offset: [62, -26] });
lP.div.style.textAlign = 'left';
lP.div.style.lineHeight = '1.35';
lP.div.style.color = '#000';

const lRho = mathLabel('<i>&rho;</i>', new THREE.Vector3(0, 0, 0), { color: '#1F5C8B', fontSize: '18px', offset: [-4, -17] });
const lPhi = mathLabel('<i>&phi;</i>', new THREE.Vector3(0, 0, 0), { fontSize: '17px', offset: [-13, -3] });
const lTh = mathLabel('<i>&theta;</i>', new THREE.Vector3(0, 0, 0), { fontSize: '17px', offset: [-4, 11] });
const lR = mathLabel('<i>r</i>', new THREE.Vector3(0, 0, 0), { color: '#E8622A', fontSize: '17px', offset: [0, 19] });
const lZd = mathLabel('<i>z</i>', new THREE.Vector3(0, 0, 0), { color: '#E8622A', fontSize: '17px', offset: [16, 0] });
const lPx = mathLabel('<i>x</i>', new THREE.Vector3(0, 0, 0), { color: '#5F8A76', fontSize: '14px', offset: [-14, 10] });
const lPy = mathLabel('<i>y</i>', new THREE.Vector3(0, 0, 0), { color: '#5F8A76', fontSize: '14px', offset: [4, 17] });

/* ── opacity groups (crossfade between readouts) ─────────────────────────── */
const GROUPS = {
  rho: { mats: [rhoMat], labs: [lRho], objs: [] },
  phi: { mats: [arcPhiMat, tipPhi.material], labs: [lPhi], objs: [] },
  theta: { mats: [arcThMat, tipTh.material], labs: [lTh], objs: [] },
  r: { mats: [rDash.material, raMat], labs: [lR], objs: [] },
  zc: { mats: [zDash.material], labs: [lZd], objs: [] },
  proj: { mats: PROJ.map(p => p.material), labs: [lPx, lPy], objs: PROJ.map(p => p.object), hard: true }
};
// Spherical (the printed default) shows the whole construction at FULL strength,
// exactly like the source. Other modes de-emphasise by dimming what is not read.
const TARGETS = {
  sph: { rho: 1.00, phi: 1.00, theta: 1.00, r: 1.00, zc: 1.00, proj: 0.00 },
  cyl: { rho: 0.30, phi: 0.15, theta: 1.00, r: 1.00, zc: 1.00, proj: 0.00 },
  rect: { rho: 0.25, phi: 0.12, theta: 0.40, r: 0.45, zc: 1.00, proj: 1.00 }
};
const curOp = Object.assign({}, TARGETS.sph);

function applyOpacity() {
  for (const k in GROUPS) {
    const G = GROUPS[k], o = curOp[k];
    G.mats.forEach(m => { m.opacity = o; });
    if (G.hard) G.objs.forEach(ob => { ob.visible = o > 0.03; });
    G.labs.forEach(L => {
      if (o < 0.05) { L.div.style.visibility = 'hidden'; }
      else { L.div.style.visibility = 'visible'; L.div.style.opacity = o; }
    });
  }
}

/* ── geometry update ─────────────────────────────────────────────────────── */
const _P = new THREE.Vector3(), _Q = new THREE.Vector3(), _vr = new THREE.Vector3();

function update() {
  const rho = S.rho, th = DEG(S.theta), ph = DEG(S.phi);
  const r = rho * Math.sin(ph);
  const mz = rho * Math.cos(ph);
  const mx = r * Math.cos(th), my = r * Math.sin(th);

  _P.set(my, mz, mx);
  _Q.set(my, 0, mx);
  _vr.set(Math.sin(th), 0, Math.cos(th));

  ptP.position.copy(_P);

  // rho cylinder
  const len = _P.length();
  if (len > 0.02) {
    rhoSeg.visible = true;
    rhoSeg.position.copy(_P).multiplyScalar(0.5);
    orient(rhoSeg, _P.clone());
    rhoSeg.scale.set(1, len, 1);
  } else rhoSeg.visible = false;

  // orange construction
  if (r > 0.05) rDash.set(ORG, _Q); else rDash.clear();
  if (Math.abs(mz) > 0.05) zDash.set(_Q, _P); else zDash.clear();
  spanTube(proxyR, ORG, _Q);
  spanTube(proxyZ, _Q, _P);

  const s = 0.30;
  const showRA = r > 0.5 && Math.abs(mz) > 0.5;
  if (showRA) {
    const u = _vr.clone().multiplyScalar(-s);
    const w = new THREE.Vector3(0, mz >= 0 ? s : -s, 0);
    const A = _Q.clone().add(u), B = _Q.clone().add(u).add(w), C = _Q.clone().add(w);
    spanTube(raA, A, B);
    spanTube(raB, B, C);
  } else { raA.visible = false; raB.visible = false; }

  // phi arc: from +Y (z-axis) toward vr
  const pPts = [];
  for (let i = 0; i <= NA; i++) {
    const t = ph * i / NA;
    pPts.push(new THREE.Vector3(
      Math.sin(t) * R_PHI * _vr.x,
      Math.cos(t) * R_PHI,
      Math.sin(t) * R_PHI * _vr.z));
  }
  setPts(arcPhi, pPts);
  const showPhi = S.phi > 3 && rho > 0.05;
  arcPhi.visible = showPhi; tipPhi.visible = showPhi;
  if (showPhi) {
    const e = pPts[NA];
    const tg = new THREE.Vector3(Math.cos(ph) * _vr.x, -Math.sin(ph), Math.cos(ph) * _vr.z);
    tipPhi.position.copy(e); orient(tipPhi, tg);
    lPhi.pos.copy(pPts[Math.round(NA / 2)]).multiplyScalar(1.45);
  }

  // theta arc in ground plane: +Z (math +x) → vr
  const tPts = [];
  for (let i = 0; i <= NA; i++) {
    const t = th * i / NA;
    tPts.push(new THREE.Vector3(Math.sin(t) * R_TH, 0, Math.cos(t) * R_TH));
  }
  setPts(arcTh, tPts);
  const showTh = S.theta > 3 && r > 0.25;
  arcTh.visible = showTh; tipTh.visible = showTh;
  if (showTh) {
    tipTh.position.copy(tPts[NA]);
    tipTh.quaternion.setFromUnitVectors(UPV,
      new THREE.Vector3(Math.cos(th), 0, -Math.sin(th)).normalize());
    const tm = th / 2;
    lTh.pos.set(Math.sin(tm) * R_TH * 1.5, 0, Math.cos(tm) * R_TH * 1.5);
  }

  // rectangular projections (geometry always current; visibility from mode)
  const A2 = new THREE.Vector3(0, 0, mx);   // (x,0,0) in math coords
  const B2 = new THREE.Vector3(my, 0, 0);   // (0,y,0) in math coords
  prOA.set(ORG, A2, 0.16, 0.11); prAQ.set(A2, _Q, 0.16, 0.11);
  prOB.set(ORG, B2, 0.16, 0.11); prBQ.set(B2, _Q, 0.16, 0.11);
  lPx.pos.copy(A2).multiplyScalar(0.5);
  lPy.pos.copy(B2).multiplyScalar(0.5);

  // dynamic labels
  lP.pos.copy(_P);
  lRho.pos.copy(_P).multiplyScalar(0.5);
  lR.pos.copy(_Q).multiplyScalar(0.5);
  lZd.pos.copy(_Q).lerp(_P, 0.5);

  refreshReadout();
}

/* ── readout ─────────────────────────────────────────────────────────────── */
const elRead = document.getElementById('readout');
function f3(v) { return String(Number(v.toPrecision(3))); }
function refreshReadout() {
  const rho = S.rho, th = DEG(S.theta), ph = DEG(S.phi);
  const r = rho * Math.sin(ph), mz = rho * Math.cos(ph);
  const mx = r * Math.cos(th), my = r * Math.sin(th);
  let h;
  if (S.mode === 'rect') {
    h = '<b>Rectangular</b><br>x = ' + f3(mx) + '<br>y = ' + f3(my) + '<br>z = ' + f3(mz)
      + '<br><span style="color:#667">x = &rho; sin&phi; cos&theta;</span>';
  } else if (S.mode === 'cyl') {
    h = '<b>Cylindrical</b><br>r = ' + f3(r) + '<br>&theta; = ' + f3(S.theta) + '&deg;<br>z = ' + f3(mz)
      + '<br><span style="color:#667">r = &rho; sin&phi;, z = &rho; cos&phi;</span>';
  } else {
    h = '<b>Spherical</b><br>&rho; = ' + f3(rho) + '<br>&theta; = ' + f3(S.theta) + '&deg;<br>&phi; = ' + f3(S.phi) + '&deg;'
      + '<br><span style="color:#667">&rho; = &radic;(x&sup2;+y&sup2;+z&sup2;)</span>';
  }
  elRead.innerHTML = h;
  document.getElementById('vrho').textContent = f3(S.rho);
  document.getElementById('vth').textContent = f3(S.theta) + '\u00B0';
  document.getElementById('vph').textContent = f3(S.phi) + '\u00B0';

  // Stacked P labels: both stay solid black at full opacity (as printed);
  // the triple currently being read is simply set in bold.
  const rectOn = S.mode === 'rect', sphOn = S.mode === 'sph', cylOn = S.mode === 'cyl';
  let html =
    '<span style="font-weight:' + (rectOn ? '700' : '400') + '">P(<i>x</i>, <i>y</i>, <i>z</i>)</span><br>' +
    '<span style="font-weight:' + (sphOn ? '700' : '400') + '">P(<i>&rho;</i>, <i>&theta;</i>, <i>&phi;</i>)</span>';
  if (cylOn) html += '<br><span style="font-weight:700;color:#E8622A">P(<i>r</i>, <i>&theta;</i>, <i>z</i>)</span>';
  lP.div.innerHTML = html;
}

/* ── controls ────────────────────────────────────────────────────────────── */
const sRho = document.getElementById('sRho');
const sTheta = document.getElementById('sTheta');
const sPhi = document.getElementById('sPhi');

function syncSliders() {
  sRho.value = S.rho; sTheta.value = S.theta; sPhi.value = S.phi;
}
function onSlide() {
  tween = null; stopPlay();
  S.rho = +sRho.value; S.theta = +sTheta.value; S.phi = +sPhi.value;
  update();
}
sRho.addEventListener('input', onSlide);
sTheta.addEventListener('input', onSlide);
sPhi.addEventListener('input', onSlide);

const btnRect = document.getElementById('mRect');
const btnCyl = document.getElementById('mCyl');
const btnSph = document.getElementById('mSph');
function setMode(m) {
  S.mode = m;
  btnRect.classList.toggle('active', m === 'rect');
  btnCyl.classList.toggle('active', m === 'cyl');
  btnSph.classList.toggle('active', m === 'sph');
  refreshReadout();
}
btnRect.addEventListener('click', () => { stopPlay(); setMode('rect'); });
btnCyl.addEventListener('click', () => { stopPlay(); setMode('cyl'); });
btnSph.addEventListener('click', () => { stopPlay(); setMode('sph'); });

/* ── demo steps ──────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The spherical triple', text: 'One distance \u03C1 and two angles \u03B8 and \u03C6 pin down P. The blue segment is \u03C1, the arc at the z-axis is \u03C6, and the arc in the floor is \u03B8.', st: { rho: 5, theta: 65, phi: 60, mode: 'sph' } },
  { title: 'Stretch \u03C1', text: 'Increasing \u03C1 pushes P straight out along the same ray. Both angles are untouched, so the direction is fixed and only the distance changes.', st: { rho: 6, theta: 65, phi: 60, mode: 'sph' } },
  { title: 'Swing \u03B8', text: '\u03B8 rotates the entire triangle about the z-axis. The height z and the ground distance r stay the same \u2014 P traces a horizontal circle.', st: { rho: 5, theta: 140, phi: 60, mode: 'sph' } },
  { title: 'Tip \u03C6 toward the pole', text: 'Shrinking \u03C6 tilts \u03C1 up toward the z-axis: the dashed r collapses while the dashed z grows, since r = \u03C1 sin \u03C6 and z = \u03C1 cos \u03C6.', st: { rho: 5, theta: 65, phi: 25, mode: 'sph' } },
  { title: 'Same point, cylindrical', text: 'Hold the point still and read it as (r, \u03B8, z). The orange ground segment and orange vertical drop are the featured quantities \u2014 \u03B8 carries over unchanged.', st: { rho: 5, theta: 65, phi: 60, mode: 'cyl' } },
  { title: 'Same point, rectangular', text: 'Finally read it as (x, y, z): r splits into x = r cos \u03B8 and y = r sin \u03B8, while z is the same vertical drop all three systems share.', st: { rho: 5, theta: 65, phi: 60, mode: 'rect' } }
];
let stepIdx = 0, tween = null, playTimer = null;
const elTitle = document.getElementById('stepTitle');
const elText = document.getElementById('stepText');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  elTitle.textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + s.title;
  elText.textContent = s.text;
  setMode(s.st.mode);
  tween = {
    from: { rho: S.rho, theta: S.theta, phi: S.phi },
    to: { rho: s.st.rho, theta: s.st.theta, phi: s.st.phi },
    t0: performance.now(), dur: 900
  };
}
document.getElementById('bNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('bPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
const bPlay = document.getElementById('bPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; bPlay.textContent = '\u25B6 Play'; bPlay.classList.remove('active'); }
}
bPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  bPlay.textContent = '\u2016 Pause'; bPlay.classList.add('active');
  goToStep(stepIdx + 1);
  playTimer = setInterval(() => goToStep(stepIdx + 1), 3600);
});

